import {communityAdmin,communityPreview} from './community-client.mjs';
import {blankCommunityEntry,validateCommunityEntry,communityLabel} from './community-model.mjs';
import {confirmDialog} from './site-dialogs.mjs?v=1';
const el=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e};
const titles={code:'Redeem Codes',patch:'Official Patch Notes',creator:'Creators'},routes={code:'redeem-codes',patch:'patch-notes',creator:'creators'},root=new URL('.',import.meta.url);
export function installCommunity({status}){
 let rows=[],kind='code',active=null,values=blankCommunityEntry(kind),dirty=false,busy=false;
 const panel=el('section',undefined,'admin-panel community-admin-panel');panel.id='community-panel';panel.hidden=true;
 panel.innerHTML=`<div class="community-admin-heading"><div><h2>Redeem Codes</h2><p>Add entries, preview your changes, then publish.</p></div><button type="button" id="community-add">Add code</button></div><p id="community-admin-status" role="status"></p><div class="community-admin-layout"><aside class="community-records"><label>Find an entry<input type="search" id="community-entry-search" placeholder="Search entries"></label><div id="community-record-list"></div></aside><div class="community-editor"><div id="community-editor-empty"><h3>Add your first code</h3><p>Create a draft to get started.</p></div><form id="community-form" hidden><div class="community-editor-meta"></div><div class="community-fields"></div><div class="community-admin-actions"><button type="submit" data-community-action="save">Save draft</button><button type="button" data-community-action="preview">Preview</button><button type="button" data-community-action="publish" class="community-publish">Publish</button><button type="button" data-community-action="unpublish">Unpublish</button></div><p class="community-editor-message" role="status"></p></form><div class="community-preview-frame" hidden><div><strong>Page preview</strong><a target="_blank" rel="noopener">Open full page</a></div><iframe title="Community page preview"></iframe></div></div></div>`;
 document.getElementById('admin-tools').append(panel);const sidebar=document.querySelector('.admin-sidebar'),nav=[];
 for(const k of ['code','patch','creator']){const b=el('button');b.type='button';b.dataset.panel='community-panel';b.dataset.communityKind=k;b.setAttribute('aria-pressed','false');b.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" aria-hidden="true"><rect x="4" y="3" width="16" height="18" rx="2"/><path d="M8 8h8M8 12h8M8 16h5"/></svg>';b.append(el('span',titles[k]));const before=sidebar.querySelector('.sidebar-bottom');before?sidebar.insertBefore(b,before):sidebar.append(b);b.addEventListener('click',()=>selectKind(k));nav.push(b);}
 const $=s=>panel.querySelector(s),form=$('#community-form'),fields=$('.community-fields'),list=$('#community-record-list'),message=$('.community-editor-message'),preview=$('.community-preview-frame');
 function meta(){if(form.hidden)return;$('.community-editor-meta').textContent=(active?'Revision '+active.revision+' · '+(active.published?'Published':'Draft'):'New draft')+(dirty?' · Unsaved changes':'');}
 function enabled(){for(const b of panel.querySelectorAll('button'))b.disabled=busy;$('[data-community-action="unpublish"]').disabled=busy||!active?.published;for(const input of fields.querySelectorAll('input,textarea,select,button'))input.disabled=busy;}
 function paintList(){const search=$('#community-entry-search').value.trim().toLowerCase();list.replaceChildren();const entries=rows.filter(r=>r.kind===kind&&communityLabel(kind,r.draft).toLowerCase().includes(search));for(const row of entries){const b=el('button',undefined,'community-record');b.type='button';b.setAttribute('aria-pressed',String(active?.id===row.id));b.append(el('strong',communityLabel(kind,row.draft)),el('small',row.published?'Published':'Draft'));b.onclick=async()=>{if(dirty&&!await confirmDialog('Discard unsaved changes?'))return;active=row;values=structuredClone(row.draft);dirty=false;paintEditor();paintList();};list.append(b);}if(!entries.length)list.append(el('p',search?'No matching entries.':'No entries yet.','community-list-empty'));}
 function field(key,label,type='text',{placeholder='',required=false,options}={}){const wrapper=el('label',label),input=el(type==='textarea'?'textarea':options?'select':'input');input.name=key;input.setAttribute('aria-label',label);if(type!=='textarea'&&!options)input.type=type;if(type==='textarea')input.rows=4;if(type==='checkbox'){wrapper.className='community-admin-check';input.checked=values[key]===true;}else input.value=values[key]??'';if(options)for(const value of options){const o=new Option(value,value);input.append(o);}if(options)input.value=values[key];input.placeholder=placeholder;input.required=required;input.oninput=()=>{values[key]=type==='checkbox'?input.checked:input.value;dirty=true;meta();};wrapper.append(input);fields.append(wrapper);return input;}
 function videoFields(){const section=el('section',undefined,'community-video-editor');section.append(el('h3','Selected videos'));for(const [i,video] of values.videos.entries()){const row=el('div',undefined,'community-video-row');for(const [key,label] of [['title','Video title'],['url','YouTube video link'],['topic','Topic'],['thumbnail','Thumbnail URL or local image path']]){const l=el('label',label),input=el('input');input.type=key==='url'?'url':'text';input.value=video[key]||'';input.setAttribute('aria-label',label+' '+(i+1));input.oninput=()=>{video[key]=input.value;dirty=true;meta();};l.append(input);row.append(l);}const remove=el('button','Remove video');remove.type='button';remove.onclick=()=>{values.videos.splice(i,1);dirty=true;paintEditor();};row.append(remove);section.append(row);}const add=el('button','Add video');add.type='button';add.disabled=values.videos.length>=12;add.onclick=()=>{values.videos.push({title:'',url:'',topic:'',thumbnail:''});dirty=true;paintEditor();};section.append(add);fields.append(section);}
 function paintEditor(){form.hidden=false;$('#community-editor-empty').hidden=true;fields.replaceChildren();message.textContent='';preview.hidden=true;if(kind==='code'){field('code','Code','text',{placeholder:'Enter the exact code'});field('rewards','Rewards','textarea',{placeholder:'Describe the published reward'});field('status_override','Working status','text',{options:['Auto','Working','Not working']});const threshold=field('dislike_threshold','Dislikes allowed before Not working','number');threshold.min='0';threshold.max='100000';threshold.step='1';field('expires_on','Expiry date (UTC, optional)','date');field('checked_on','Last checked','date');field('source_url','Source link (optional)','url');field('note','Requirements or notes','textarea');}else if(kind==='patch'){field('title','Title');field('version','Game version (optional)');field('released_on','Release date (UTC)','date');const timing=el('p',values.released_on?(values.released_on>new Date().toISOString().slice(0,10)?'Upcoming patch':'Patch notes'):'Set the official release date before publishing.','community-list-empty');fields.append(timing);fields.querySelector('[name=released_on]').addEventListener('input',e=>{timing.textContent=e.target.value?(e.target.value>new Date().toISOString().slice(0,10)?'Upcoming patch':'Patch notes'):'Set the official release date before publishing.';});field('source_url','Official announcement link','url');field('summary','Companion site summary (optional)','textarea');field('source_verified','I checked that this is an official developer announcement','checkbox');}else{field('name','Creator name');field('description','Description','textarea');field('channel_url','YouTube channel link','url');field('avatar_url','Profile image URL or local creator image');field('creator_code','Creator code (optional)');field('featured','Featured creator','checkbox');videoFields();}meta();enabled();}
 async function selectKind(next){if(dirty&&!await confirmDialog('Discard unsaved changes?'))return;kind=next;active=null;dirty=false;values=blankCommunityEntry(kind);$('#community-entry-search').value='';$('.community-admin-heading h2').textContent=titles[kind];$('#community-add').textContent=kind==='code'?'Add code':kind==='patch'?'Add patch notes':'Add creator';$('#community-editor-empty h3').textContent='Add or select '+(kind==='code'?'a code':kind==='patch'?'patch notes':'a creator');form.hidden=true;$('#community-editor-empty').hidden=false;preview.hidden=true;for(const b of nav)b.setAttribute('aria-pressed',String(b.dataset.communityKind===kind));paintList();}
 async function save(){const content=validateCommunityEntry(kind,values);const next=await communityAdmin(active?'save':'create',active?{id:active.id,revision:active.revision,content}:{kind,content});active=next;values=structuredClone(next.draft);dirty=false;rows=await communityAdmin('list');paintList();meta();return next;}
 async function work(fn){if(busy)return;busy=true;enabled();message.textContent='';try{await fn();}catch(error){message.textContent=error.message;status(error.message);}finally{busy=false;enabled();}}
 $('#community-add').onclick=async()=>{if(dirty&&!await confirmDialog('Discard unsaved changes?'))return;active=null;values=blankCommunityEntry(kind);dirty=false;paintList();paintEditor();fields.querySelector('input,textarea')?.focus();};
 $('#community-entry-search').oninput=paintList;
 form.onsubmit=e=>{e.preventDefault();work(async()=>{await save();message.textContent='Draft saved.';status(communityPreview?'Local draft saved.':'Draft saved.');});};
 $('[data-community-action="preview"]').onclick=()=>work(async()=>{await save();const url=new URL('./information/'+routes[kind]+'.html',root);url.searchParams.set('draft',active.id);if(communityPreview)url.searchParams.set('preview','1');preview.querySelector('iframe').src=url;preview.querySelector('a').href=url;preview.hidden=false;message.textContent='Previewing your saved draft.';});
 $('[data-community-action="publish"]').onclick=()=>work(async()=>{validateCommunityEntry(kind,values,{publish:true});if(dirty||!active)await save();active=await communityAdmin('publish',{id:active.id,revision:active.revision});rows=await communityAdmin('list');values=structuredClone(active.draft);paintList();meta();message.textContent=communityPreview?'Published to this local preview.':'Published. The public page is updated.';status(message.textContent);});
 $('[data-community-action="unpublish"]').onclick=()=>work(async()=>{if(!await confirmDialog('Unpublish this entry? Its draft will stay available.'))return;active=await communityAdmin('unpublish',{id:active.id,revision:active.revision});rows=await communityAdmin('list');paintList();meta();message.textContent=communityPreview?'Removed from the local public preview.':'Unpublished. The draft is kept.';status(message.textContent);});
 async function refresh(){try{rows=await communityAdmin('list');paintList();$('#community-admin-status').textContent='';}catch(error){$('#community-admin-status').textContent=error.message;}}
 return {refresh,async startPreview(){document.body.classList.add('community-admin-preview');for(const b of document.querySelectorAll('.admin-sidebar [data-panel]'))if(!b.dataset.communityKind)b.hidden=true;for(const old of document.querySelectorAll('.admin-panel'))old.hidden=old!==panel;panel.hidden=false;await refresh();await selectKind('code');}};
}
